-- Prompt 8 schema reference for Supabase. Apply only after review and migration generation.
create type trial_request_status as enum ('draft','requested','viewed','accepted','rejected','proposed_new_time','cancelled_by_learner','cancelled_by_instructor','expired','completed','no_show');
create type class_session_status as enum ('scheduled','waiting_room','live','completed','cancelled','no_show');
create table trial_requests (id uuid primary key default gen_random_uuid(), learner_id uuid not null references profiles(id), instructor_id uuid not null references profiles(id), course_id uuid null, requirement_id uuid null, subject text not null, preferred_language text not null, learner_level text not null, learning_goal text not null, requested_start_at timestamptz not null, requested_end_at timestamptz not null, learner_timezone text not null, instructor_timezone text not null, learner_message text not null, instructor_response text null, proposed_start_at timestamptz null, proposed_end_at timestamptz null, status trial_request_status not null default 'draft', cancellation_reason text null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint trial_request_time_order check (requested_end_at > requested_start_at));
create table class_sessions (id uuid primary key default gen_random_uuid(), trial_request_id uuid null references trial_requests(id), course_id uuid null, learner_id uuid not null references profiles(id), instructor_id uuid not null references profiles(id), subject text not null, title text not null, session_type text not null check (session_type in ('trial','course')), scheduled_start_at timestamptz not null, scheduled_end_at timestamptz not null, learner_timezone text not null, instructor_timezone text not null, status class_session_status not null default 'scheduled', live_provider text null, external_session_id text null, recording_status text not null default 'not_configured', learner_joined_at timestamptz null, instructor_joined_at timestamptz null, ended_at timestamptz null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint class_session_time_order check (scheduled_end_at > scheduled_start_at));
create table notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles(id), type text not null, title text not null, body text not null, related_entity_type text not null, related_entity_id uuid null, read_at timestamptz null, created_at timestamptz not null default now());
alter table trial_requests enable row level security; alter table class_sessions enable row level security; alter table notifications enable row level security;
-- RLS: learners select/insert only rows where learner_id = auth.uid(); instructors select/update only rows where instructor_id = auth.uid(); participants select sessions only when learner_id or instructor_id = auth.uid(); notification recipients select/update only user_id = auth.uid(). Status transitions, double-booking, availability conflicts, cancellation reasons, and attendance timestamps must be validated in server-side procedures or database functions. Service-role keys, email provider secrets, and live-provider tokens never appear in the client.
